def get_lang(context) -> str:
    return context.user_data.get("lang", "ru") if context and hasattr(context, "user_data") else "ru"

def t(key: str, context, **kwargs) -> str:
    lang = get_lang(context)
    entry = TRANSLATIONS.get(key, {})
    text = entry.get(lang) or entry.get("ru") or f"[{key}]"
    if kwargs:
        try: text = text.format(**kwargs)
        except: pass
    return text

def get_property_type_name(ptype_key: str, lang: str) -> str:
    entry = TRANSLATIONS.get(f"ptype_{ptype_key}", {})
    return entry.get(lang) or entry.get("ru") or ptype_key

def get_district_name(district_key: str, lang: str) -> str:
    entry = TRANSLATIONS.get(f"district_{district_key}", {})
    return entry.get(lang) or entry.get("ru") or district_key

def get_infra_name(infra_key: str, lang: str) -> str:
    entry = TRANSLATIONS.get(f"infra_{infra_key}", {})
    return entry.get(lang) or entry.get("ru") or infra_key

def is_rtl(lang: str) -> bool:
    return lang in RTL_LANGS

